# -*- coding: utf-8 -*-
# 第 11 批（C4）：危險性機械及設備安全檢查規則（OSH-53）第144條～第168條、
#                既有危險性機械及設備安全檢查規則（OSH-54）全部（補題）
# ※ 四個選項刻意寫成相近長度。
L = "OSH-53"; E = "OSH-54"
Q = [
(L,"第144條",2,"高壓氣體容器-型式檢查",
 "高壓氣體容器之製造或修改，申請型式檢查應檢附載有哪些事項之書件？",
 ["型式構造詳圖及強度計算書、製造檢查設備之種類能力及數量、主任設計者與施工負責人學經歷概要、施工者資格及人數；以熔接者另附熔接人員資格證件與熔接程序規範及資格檢定紀錄","型式構造詳圖及強度計算書、容器灌裝氣體種類及灌裝場所位置圖、灌裝作業標準書、容器搬運車輛清冊、駕駛人員名冊及訓練證書、灌氣容器儲存場所之配置圖等文件","工廠登記證及公司登記證明文件、最近三年財務報表、勞工保險投保名冊、職業安全衛生管理計畫、自動檢查計畫、緊急應變計畫及教育訓練紀錄等行政管理性質之文件","歷次檢查合格證影本及定期檢查結果報告表、內部檢查照片、超音波測厚紀錄、耐壓試驗與氣密試驗紀錄、防銹塗飾檢查紀錄及非破壞檢查報告書等歷史檢查文件"],"a",
 "第144條：高壓氣體容器之製造或修改，製造人應於事前填具型式檢查申請書，檢附型式、構造詳圖及強度計算書、製造與檢查設備之種類能力及數量、主任設計者與施工負責人學經歷概要、施工者資格及人數，以熔接製造或修改者並應檢附熔接人員資格證件、熔接程序規範及熔接程序資格檢定紀錄；未經檢查合格不得製造或修改，但與業經型式檢查合格之型式及條件相同者不在此限。",
 "What documents must accompany a type inspection application for a high pressure gas container?",
 ["Type, detailed drawings and strength calculations, kinds, capacity and number of manufacturing and testing facilities, records of the chief designer and supervisor, workers' qualifications and numbers, plus welding credentials and procedure records","Type, detailed drawings and strength calculations, the gases to be filled and a plan of the filling site, the filling work standard, a list of transport vehicles, the drivers' roster and training certificates and the storage layout","The factory and company registration documents, three years of financial statements, the labor insurance roster, the safety and health management plan, the automatic inspection plan, the emergency response plan and training records","Copies of past inspection certificates and periodic result reports, internal inspection photographs, ultrasonic thickness records, pressure and airtightness test records, anti-rust coating checks and non-destructive testing reports"],
 "Article 144."),

(L,"第145條",3,"高壓氣體容器-製造設備",
 "高壓氣體容器製造人應設置適應容器製造必要之設備，下列敘述何者正確？",
 ["無縫容器應具鍛造或成型設備、以接合底部製造者之底部接合設備、使用熱處理材料者之退火爐及爐內溫度測定裝置、洗滌設備、確認厚度之器具；無縫容器以外者另應具成型設備、熔接或硬焊設備及防銹塗裝設備","無縫容器應具彎板機、衝床、萬能試驗機及放射線檢查設備；無縫容器以外者另應具鑄造設備、水壓試驗設備及挖製裝置；至於洗滌設備、退火爐與確認厚度之器具，均得以委外檢驗方式替代而免設置","無縫容器與無縫容器以外之容器，均僅需具備水壓試驗設備及氣密試驗設備即可；至於成型設備、熔接或硬焊設備、防銹塗裝設備及確認厚度之器具，得由製造人視實際製造需要自行決定是否設置","無縫容器與無縫容器以外之容器所需設備，一律由中央主管機關逐案指定；製造人僅須於申請型式檢查時檢附設備清單，並由檢查機構於現場查核其數量是否足敷所申請製造之容器種類及數量"],"a",
 "第145條：高壓氣體容器之製造人應實施品管及品保措施，其設備及人員除準用第96條規定外，無縫容器應設置鍛造設備或成型設備、以接合底部製造者之底部接合設備、以使用熱處理材料製造者之退火爐及可測定該爐內溫度之溫度測定裝置、洗滌設備、確認厚度之器具；無縫容器以外之容器除設置前款第3目至第5目設備外，並應設置成型設備、熔接設備或硬焊設備、防銹塗裝設備（但製造灌裝液化石油氣之容器，使用不銹鋼、鋁合金或其他不易腐蝕材料者除外）。",
 "Which statement about the facilities a high pressure gas container maker must have is correct?",
 ["Seamless containers need forging or forming equipment, bottom joining equipment if bottoms are joined, an annealing furnace with a temperature gauge if heat treated material is used, washing equipment and thickness gauges; others add forming, welding or brazing and anti-rust coating equipment","Seamless containers need plate bending machines, presses, universal testing machines and radiographic equipment; others add casting equipment, hydrostatic test facilities and boring devices, while washing equipment, annealing furnaces and thickness gauges may all be outsourced","Both seamless containers and other containers need only hydrostatic test and airtightness test equipment; forming equipment, welding or brazing equipment, anti-rust coating equipment and thickness gauges are provided or not as the maker sees fit for its own production","The facilities required for seamless and other containers are designated case by case by the central competent authority; the maker merely attaches an equipment list when applying, the agency checking on site whether the quantity suffices for the containers applied for"],
 "Article 145."),

(L,"第146條",2,"高壓氣體容器-熔接檢查",
 "以熔接製造之高壓氣體容器，於何種情形得免申請熔接檢查？",
 ["附屬設備或僅對不產生壓縮應力以外之應力部分施以熔接者；或僅就內徑在三百公厘以下管之圓周接頭、加強材料管管台凸緣閥座熔接於胴體端板、支持架等不承受壓力物件之熔接及防漏熔接者","附屬設備或僅對產生壓縮應力部分施以熔接者；或僅就內徑在六百公厘以下管之圓周接頭、加強材料管管台凸緣閥座熔接於胴體端板、支持架等承受壓力物件之熔接及防漏熔接者，均得免申請","凡以熔接製造之高壓氣體容器均應申請熔接檢查而無任何例外；惟檢查機構得視實際情形要求製造人另行實施熱處理檢查、放射線檢查及熔接部之機械性能試驗等各該必要之項目","凡內容積未滿五百公升或最高灌裝壓力未超過每平方公分十公斤者，均得免申請熔接檢查；其餘情形應於製造完成後併同構造檢查一併向製造所在地之檢查機構申請辦理熔接檢查"],"a",
 "第146條：以熔接製造之高壓氣體容器，應於施工前由製造人向製造所在地檢查機構申請熔接檢查；但附屬設備或僅對不產生壓縮應力以外之應力部分施以熔接者，或僅就內徑在三百公厘以下之管之圓周接頭、加強材料管管台凸緣及閥座等熔接在胴體或端板上、支持架或其他不承受壓力物件熔接於胴體端板、防漏熔接等部分施以熔接者，不在此限。熔接檢查項目為材料檢查、外表檢查、熔接部之機械性能試驗、放射線檢查、熱處理檢查及其他必要檢查。",
 "When is a welded high pressure gas container exempt from applying for a welding inspection?",
 ["Where only accessories or parts bearing stresses other than compressive are welded; or where welding is confined to circumferential joints of pipes up to 300 mm bore, reinforcements, nozzles, flanges and valve seats, non-pressure supports and seal welds","Where only accessories or parts bearing compressive stress are welded; or where welding is confined to circumferential joints of pipes up to 600 mm bore, reinforcements, nozzles, flanges and valve seats, pressure-bearing supports and every seal weld","Every welded high pressure gas container must apply for a welding inspection with no exception at all; the agency may however require heat treatment inspection, radiography and mechanical property testing of the weld as it sees fit","Any container under 500 litres or with a maximum filling pressure not over 10 kg/cm2 is exempt; otherwise the welding inspection is applied for to the agency of the place of manufacture together with the structural inspection"],
 "Article 146."),

(L,"第147條",2,"高壓氣體容器-熔接申請",
 "製造人申請高壓氣體容器熔接檢查時，應檢附哪些書件？",
 ["材質證明一份、熔接明細表二份、構造詳圖及強度計算書各二份、熔接施工人員之熔接技術士資格證件、型式檢查合格證明與熔接程序規範及資格檢定紀錄影本各一份","材質證明二份、灌裝氣體種類申報表一份、容器搬運車輛清冊及駕駛人員名冊各一份、灌氣容器儲存場所配置圖二份及最近一次定期檢查結果報告表影本一份等文件","加蓋構造檢查合格戳記之容器明細表二份、竣工檢查結果報告表一份、耐壓試驗紀錄、氣密試驗紀錄及防銹塗飾檢查紀錄各一份，並附前經檢查合格證明文件之影本","公司登記證明文件、工廠登記證影本、勞工保險投保名冊、職業安全衛生管理計畫、自動檢查計畫及緊急應變計畫各一份等行政管理性質之相關證明文件資料"],"a",
 "第147條：製造人申請高壓氣體容器之熔接檢查時，應填具高壓氣體容器熔接檢查申請書，並檢附材質證明一份、熔接明細表二份、構造詳圖及強度計算書各二份、熔接施工人員之熔接技術士資格證件、製造設施型式檢查合格證明與熔接程序規範及熔接程序資格檢定紀錄等影本各一份。與鍋爐、第一種壓力容器不同，高壓氣體容器毋須另附施工位置分類圖。",
 "What documents must accompany a welding inspection application for a high pressure gas container?",
 ["One material certificate, two welding schedules, two sets each of detailed drawings and strength calculations, the welders' skill certificates, and one copy each of the type certificate and the welding procedure records","Two material certificates, one declaration of the gases to be filled, a list of transport vehicles and the drivers' roster, two storage site layouts and one copy of the latest periodic inspection result report","Two container specification tables bearing the structural pass stamp, one completion inspection result report, pressure test records, airtightness test records and anti-rust coating records, plus the previous certificate","The company registration documents, a copy of the factory registration, the labor insurance roster, the safety and health management plan, the automatic inspection plan and the emergency response plan, one each"],
 "Article 147."),

(L,"第148條",1,"高壓氣體容器-熔接程序",
 "檢查機構實施高壓氣體容器熔接檢查之程序及現場準備事項為何？",
 ["應就書件先行審查合格後實施現場實物檢查；現場檢查時製造人或其指派人員應在場，並事前備妥機械性能試驗片及放射線檢查","應先實施現場實物檢查合格後再審查書件；現場檢查時雇主或其指派人員應在場，並事前備妥荷重試驗用荷物及必要之吊掛器具","得僅實施書面審查而免現場實物檢查；如認有必要實施現場檢查時，由檢查機構自行備妥機械性能試驗片及放射線檢查之設備","應由製造人自行實施現場實物檢查並作成紀錄；檢查機構僅就其提送之紀錄實施書面審查，並將審查之結果通知申請人即可"],"a",
 "第148條：檢查機構實施高壓氣體容器之熔接檢查時，應就製造人檢附之書件先行審查合格後，依熔接檢查項目實施現場實物檢查；實施現場實物檢查時，製造人或其指派人員應在場，並應事前備妥機械性能試驗片及放射線檢查。鍋爐（第75條）、第一種壓力容器（第99條）、高壓氣體特定設備（第123條）亦同。",
 "What is the procedure and on-site preparation for a high pressure gas container's welding inspection?",
 ["Documents are reviewed and approved first, then the object is inspected on site; the maker or a designee attends and prepares mechanical test pieces and radiographic examination","The object is inspected on site and passed first, then the documents are reviewed; the employer or a designee attends and prepares the load test loads and the necessary rigging gear","A documentary review alone suffices with no on-site inspection; where one is thought necessary, the agency itself prepares the mechanical test pieces and the radiographic equipment","The maker inspects the object on site itself and records it; the agency merely reviews the records submitted and notifies the applicant of the outcome of that review of them"],
 "Article 148."),

(L,"第149條",1,"高壓氣體容器-熔接合格",
 "高壓氣體容器經熔接檢查合格者，檢查機構應如何處理？",
 ["在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人一份作為熔接檢查合格證明，並在物體明顯部位打印","在容器明細表上加蓋構造檢查合格戳記，檢查員簽章後交付申請人二份作為熔接檢查合格證明，並核發檢查合格證","逕行核發高壓氣體容器檢查合格證及定期檢查結果報告表，有效期限最長五年，並由雇主置掛於灌裝作業場所明顯處","由製造人自行於熔接明細表註記熔接檢查合格後留存備查，檢查機構僅須以書面將檢查結果通知申請人即無須打印"],"a",
 "第149條：高壓氣體容器經熔接檢查合格者，檢查機構應在熔接明細表上加蓋熔接檢查合格戳記，檢查員簽章後交付申請人一份，做為熔接檢查合格證明，並應在被檢查物體上明顯部位打印，以資識別。第151條第1項第3款：申請構造檢查時，以熔接製造者應附加蓋熔接檢查合格戳記之熔接明細表。",
 "How does the agency handle a high pressure gas container passing its welding inspection?",
 ["It stamps the welding schedule with the welding pass mark, the inspector signs, one copy is given as proof, and the object is marked conspicuously for identification","It stamps the container specification table with the structural pass mark, the inspector signs, two copies are given as proof, and an inspection certificate is issued","It directly issues the container inspection certificate and a periodic inspection result report valid at most five years, posted conspicuously at the filling site","The maker notes the welding pass on the welding schedule itself and keeps it, the agency merely notifying the applicant in writing without marking the object"],
 "Article 149."),

(L,"第150條",1,"高壓氣體容器-構造檢查",
 "高壓氣體容器製造完成時，應由何人向何機構申請構造檢查？",
 ["應由製造人向製造所在地檢查機構申請構造檢查","應由雇主向設置所在地檢查機構申請構造檢查","應由所有人向中央主管機關申請並取得認可證明","應由代行檢查機構逕行實施並報中央主管機關備查"],"a",
 "第150條：製造高壓氣體容器完成時，應由製造人向製造所在地檢查機構申請構造檢查。與第一種壓力容器（第101條）、高壓氣體特定設備（第125條）不同，本條並未設分割組合式得向設置所在地申請之例外。",
 "Who applies to which agency for the structural inspection of a completed high pressure gas container?",
 ["The maker applies to the inspection agency of the place where it was manufactured","The employer applies to the inspection agency of the place where it is installed","The owner applies to the central competent authority and obtains a recognition","A designated inspection body inspects on its own and reports it to the authority"],
 "Article 150; cf. Articles 101 and 125."),

(L,"第151條",3,"高壓氣體容器-構造項目",
 "高壓氣體容器構造檢查之項目包括下列何者？",
 ["施工方法、材料厚度、構造、尺寸、最高使用壓力、強度計算審查、氣密試驗、耐壓試驗、安全裝置、附屬品及附屬裝置、超低溫容器之絕熱性能試驗及其他必要之檢查","安全閥數量、容量、吹洩試驗、水位計數量與位置、給水裝置容量、排水裝置容量、水處理裝置、鍋爐房之設置、基礎與出入口及燃燒裝置等以設置配置為主之項目","外觀檢查、外部之腐蝕裂痕變形污穢洩漏之檢測、易腐蝕處之定點超音波測厚、附屬品及附屬裝置檢查等以外部狀況為主之項目，並得以適當儀器檢測其內部狀況","材料檢查、外表檢查、熔接部之機械性能試驗、放射線檢查及熱處理檢查等以熔接部品質為主之項目，並由製造人事前備妥機械性能試驗片及放射線檢查等事項"],"a",
 "第151條第3項：高壓氣體容器構造檢查項目為施工方法、材料厚度、構造、尺寸、最高使用壓力、強度計算審查、氣密試驗、耐壓試驗、安全裝置、附屬品及附屬裝置、超低溫容器之絕熱性能試驗及其他必要之檢查。第1項、第2項：應檢附容器明細表二份、構造詳圖及強度計算書各二份、以熔接製造者附加蓋熔接檢查合格戳記之熔接明細表、以鉚接製造者附型式檢查合格證明；由同一檢查機構實施熔接檢查及構造檢查者，得免檢附第2款及第3款書件。",
 "What does a high pressure gas container's structural inspection cover?",
 ["Construction method, material thickness, structure, dimensions, maximum working pressure, strength review, airtightness test, pressure test, safety devices, accessories and attachments, the insulation test for cryogenic containers and other necessary checks","Number and capacity of safety valves and blow-off testing, number and position of water gauges, feed and drain device capacity, water treatment, the boiler house, foundation and entrances and the burner, being matters of layout and installation","Visual inspection, detection of external corrosion, cracking, deformation, fouling and leakage, spot ultrasonic thickness measurement at corrosion-prone points and accessories and attachments, the interior being probed with suitable instruments","Material inspection, surface inspection, mechanical property testing of the weld, radiographic examination and heat treatment inspection, being matters of weld quality, with the maker preparing test pieces and radiography beforehand"],
 "Article 151."),

(L,"第152條",1,"高壓氣體容器-構造準備",
 "檢查機構實施高壓氣體容器構造檢查時，製造人應事先備妥何事項？",
 ["製造人或其指派人員應在場，並事先將被檢查物件放置於易檢查位置及準備水壓等耐壓試驗","製造人或其指派人員應在場，並事先將被檢查物件加熱至常用溫度及準備放射線檢查設備","雇主或其指派人員應在場，並事先將被檢查物件灌裝氣體至常用壓力及準備氣密試驗器材","所有人或其代理人應在場，並事先將被檢查物件完全分解為零件及準備防銹塗裝之材料"],"a",
 "第152條：檢查機構實施高壓氣體容器之構造檢查時，製造人或其指派人員應在場，並應事先備妥將被檢查物件放置於易檢查位置、準備水壓等耐壓試驗。第161條第2項、第162條之2第2項：重新檢查及變更檢查準用第151條第3項及第152條規定。",
 "What must the maker prepare for the structural inspection of a high pressure gas container?",
 ["The maker or a designee attends and beforehand places the object where it is easy to inspect and prepares a hydrostatic or other pressure test","The maker or a designee attends and beforehand heats the object to its usual working temperature and prepares the radiographic testing equipment","The employer or a designee attends and beforehand fills the object with gas to the usual pressure and prepares the airtightness testing gear","The owner or an agent attends and beforehand dismantles the object completely into parts and prepares the anti-rust coating materials needed"],
 "Article 152."),

(L,"第153條",3,"高壓氣體容器-構造合格",
 "高壓氣體容器經構造檢查合格者，檢查機構應如何處理？固定於車輛者有何特別規定？",
 ["應核發檢查合格證並在容器明細表上加蓋構造檢查合格戳記後交付申請人一份，且在物體明顯部位打印；但固定於車輛之容器，應經組裝完成並固定於車架後始得核發檢查合格證","應核發檢查合格證並在熔接明細表上加蓋熔接檢查合格戳記後交付申請人二份，且在物體明顯部位打印；固定於車輛之容器，得於車架組裝前先行核發檢查合格證以利運送","僅需在容器明細表上加蓋構造檢查合格戳記，檢查合格證須俟竣工檢查合格後始得核發；固定於車輛之容器，應由雇主另向公路監理機關申請車輛變更登記後始得使用","僅需將檢查結果以書面通知申請人並由其自行留存備查；固定於車輛之容器，應報請中央主管機關逐案核准後，由代行檢查機構核發檢查合格證並註明其使用有效期限"],"a",
 "第153條：高壓氣體容器經構造檢查合格者，檢查機構應核發檢查合格證及在高壓氣體容器明細表上加蓋構造檢查合格戳記，檢查員簽章後交付申請人一份，並應在被檢查物體上明顯部位打印，以資識別；但固定於車輛之高壓氣體容器，應經組裝完成並固定於車架後，始得核發檢查合格證。前項檢查合格證有效期限依第155條規定。",
 "How does the agency handle a high pressure gas container passing structural inspection, and what if it is vehicle-mounted?",
 ["It issues the inspection certificate, stamps the specification table with the structural pass mark and gives one copy, and marks the object; for a vehicle-mounted container the certificate issues only once assembly and mounting on the chassis are complete","It issues the inspection certificate, stamps the welding schedule with the welding pass mark and gives two copies, and marks the object; for a vehicle-mounted container the certificate may issue before chassis mounting so as to ease transport","It merely stamps the specification table with the structural pass mark, the certificate issuing only after the completion inspection is passed; a vehicle-mounted container also needs a vehicle alteration registration from the highway authority","It merely notifies the applicant of the result in writing for the applicant's own records; a vehicle-mounted container needs case-by-case approval of the central competent authority before a designated body issues its certificate"],
 "Article 153."),

(L,"第154條",1,"高壓氣體容器-定期申請",
 "雇主應於何時向檢查機構申請高壓氣體容器之定期檢查？",
 ["應於檢查合格證有效期限屆滿前一個月，填具定期檢查申請書向檢查機構申請","應於檢查合格證有效期限屆滿前六個月，填具定期檢查申請書向檢查機構申請","應於檢查合格證有效期限屆滿後一個月內，填具定期檢查申請書向檢查機構申請","應於構造檢查合格後每滿五年時，填具定期檢查申請書向中央主管機關提出申請"],"a",
 "第154條：雇主於高壓氣體容器檢查合格證有效期限屆滿前一個月，應填具定期檢查申請書向檢查機構申請定期檢查。第155條：內部檢查自構造檢查合格日起算未滿十五年者每五年一次、十五年以上未滿二十年者每二年一次、二十年以上者每年一次；無縫容器每五年一次。",
 "When must the employer apply for a high pressure gas container's periodic inspection?",
 ["One month before the inspection certificate expires, by filing a periodic inspection application with the agency","Six months before the inspection certificate expires, by filing a periodic inspection application with the agency","Within one month after the inspection certificate has expired, by filing a periodic inspection application with it","Every five years after the structural inspection is passed, by applying to the central competent authority instead"],
 "Article 154; see Article 155."),

(L,"第156條",3,"高壓氣體容器-內部延長",
 "高壓氣體容器無法依規定期限實施內部檢查者，其申請延長之時點及適用情形為何？",
 ["得於檢查合格證有效期限屆滿前三個月，檢附安全衛生管理狀況、自動檢查計畫及執行紀錄、構造詳圖、緊急應變處置計畫、安全保護裝置及檢查替代方式建議報經檢查機構核定；適用於免設人孔或無法設置者、低溫或超低溫容器、夾套式或無腐蝕之虞者及其他困難者","得於檢查合格證有效期限屆滿前一個月，檢附安全衛生管理狀況、自動檢查計畫及執行紀錄、構造詳圖及緊急應變處置計畫等資料報經當地主管機關核定；僅適用於免設人孔或構造上無法設置人孔者一種情形，其餘均應依規定期限實施內部檢查","得於檢查合格證有效期限屆滿後三個月內，檢附最近一次外部檢查結果報告表、超音波測厚紀錄及氣密試驗紀錄等資料報經中央主管機關追認；適用於容器使用年限已達二十年以上，或最高灌裝壓力未超過每平方公分十公斤之各該容器","得於檢查合格證有效期限屆滿前六個月，檢附灌裝氣體種類申報表、容器搬運車輛清冊及操作人員名冊等資料報經代行檢查機構核定；適用於經檢查機構認定外部檢查結果良好且最近三年內未曾發生洩漏事故之容器"],"a",
 "第156條：雇主對於依規定免設人孔或構造上無法設置人孔、掃除孔或檢查孔者，低溫或超低溫之高壓氣體容器，夾套式或無腐蝕之虞者，及其他實施內部檢查困難者，無法依規定期限實施內部檢查時，得於檢查合格證有效期限屆滿前三個月，檢附其安全衛生管理狀況、自動檢查計畫及執行紀錄、該容器之構造詳圖、緊急應變處置計畫、安全保護裝置及檢查替代方式建議等資料，報經檢查機構核定後，延長其內部檢查期限或以其他檢查方式替代。",
 "When and in what cases may a high pressure gas container's internal inspection interval be extended?",
 ["Three months before the certificate expires, attaching the safety management status, automatic inspection plan and records, detailed drawings, the emergency plan, protective devices and a proposed substitute for the agency to approve; for containers with no manhole, cryogenic ones, jacketed ones or no corrosion risk, and other difficult cases","One month before the certificate expires, attaching the safety management status, automatic inspection plan and records, detailed drawings and the emergency response plan for the local competent authority to approve; only where a manhole is exempt or structurally impossible, every other container being inspected on time","Within three months after the certificate expires, attaching the latest external inspection result report, ultrasonic thickness records and airtightness test records for the central competent authority to ratify; only for containers in service twenty years or more, or with a filling pressure not over 10 kg/cm2","Six months before the certificate expires, attaching a declaration of the gases filled, a list of transport vehicles and the operator roster for the designated inspection body to approve; only for containers the agency finds sound externally and free of any leakage incident in three years"],
 "Article 156."),

(L,"第157條",1,"高壓氣體容器-內部準備",
 "檢查機構受理高壓氣體容器內部檢查時，應使雇主預先辦理何事？",
 ["應將檢查日期通知雇主，使其預先將容器內部恢復至常溫、常壓、排放內容物、通風換氣、整理清掃內部及為其他定期檢查必要準備事項","應將檢查日期通知雇主，使其預先將容器灌裝至最高灌裝壓力並保持低溫、封存內容物及為其他定期檢查所必要之各項準備事項","應將檢查日期通知製造人，使其預先將容器運回原製造工廠、完全分解為零件並準備防銹塗裝材料及非破壞檢查所需之儀器","應將檢查日期公告於指定資訊網站，由檢查機構自行將容器內部排空、通風換氣及整理清掃後，再實施內部檢查之各該項目"],"a",
 "第157條：檢查機構受理實施高壓氣體容器內部檢查時，應將檢查日期通知雇主，使其預先將高壓氣體容器之內部恢復至常溫、常壓、排放內容物、通風換氣、整理清掃內部及為其他定期檢查必要準備事項。第157條之1第6項：實施內外部檢查時，雇主或其指派人員應在場。",
 "What must the employer prepare in advance for a high pressure gas container's internal inspection?",
 ["The agency notifies the date so the employer restores the interior to normal temperature and pressure, drains the contents, ventilates, cleans it and makes other necessary preparations","The agency notifies the date so the employer fills the container to its maximum filling pressure, keeps it cold with the contents sealed in and makes other necessary preparations","The agency notifies the maker so it returns the container to the original factory, dismantles it completely into parts and prepares anti-rust materials and testing instruments","The agency publishes the date on the designated website and itself empties, ventilates and cleans the interior of the container before carrying out the items of the internal inspection"],
 "Article 157."),

(L,"第157之1條",3,"高壓氣體容器-內外部檢查",
 "低溫或超低溫等高壓氣體容器之內部檢查有困難者，得以何種方式代替？另有何附加檢查？",
 ["得以常用壓力一點五倍以上壓力實施耐壓試驗，或以常用壓力一點一倍以上壓力就內容物實施耐壓試驗，並以常用壓力以上壓力實施氣密試驗及外觀檢查代替；熔接容器應實施防銹塗飾檢查，超低溫容器應實施氣密試驗","得以常用壓力一點二倍以上壓力實施耐壓試驗，或以常用壓力一點零五倍以上壓力就內容物實施耐壓試驗，並以最高灌裝壓力實施吹洩試驗及超音波測厚代替；熔接容器應實施放射線檢查，超低溫容器應實施熱處理檢查","得以最高灌裝壓力二倍以上壓力實施水壓試驗，或以設計壓力三倍以上壓力就空氣實施耐壓試驗，並以常用壓力以下壓力實施非破壞檢查代替；熔接容器應實施絕熱性能試驗，超低溫容器應實施防銹塗飾檢查","得由雇主自行以目視方式檢查容器外部並作成紀錄留存三年，無須實施任何耐壓試驗或氣密試驗；熔接容器與超低溫容器均得免除防銹塗飾檢查及氣密試驗，僅須於下次定期檢查時一併補行實施"],"a",
 "第157條之1：高壓氣體容器外部檢查項目為外觀檢查、外部腐蝕裂痕變形污穢洩漏之檢測、必要時之非破壞檢查、易腐蝕處定點超音波測厚等，發現異狀應併實施內部檢查；內部檢查項目為內部表面檢查、厚度腐蝕裂痕變形污穢等檢測、必要時之非破壞檢查及依結果判定需要之耐壓試驗；低溫或超低溫等容器之內部檢查，得以常用壓力一點五倍以上壓力實施耐壓試驗或常用壓力一點一倍以上壓力以內容物實施耐壓試驗，並以常用壓力以上壓力實施氣密試驗及外觀檢查代替；實施必要檢查時，熔接容器應實施防銹塗飾檢查，超低溫容器應實施氣密試驗。國際間運送具他國簽發檢查合格證明文件者，檢查機構得審酌免除全部或一部之檢查。",
 "How may the internal inspection of a cryogenic high pressure gas container be replaced, and what is added?",
 ["A pressure test at 1.5 times the usual pressure, or at 1.1 times using the contents, plus an airtightness test above the usual pressure and a visual inspection; welded containers also get an anti-rust coating check and cryogenic ones an airtightness test","A pressure test at 1.2 times the usual pressure, or at 1.05 times using the contents, plus a blow-off test at maximum filling pressure and thickness measurement; welded containers also get radiography and cryogenic ones a heat treatment inspection","A hydrostatic test at twice the maximum filling pressure, or an air test at three times the design pressure, plus non-destructive testing below the usual pressure; welded containers also get an insulation test and cryogenic ones an anti-rust check","The employer visually checks the exterior and keeps the record three years, with no pressure or airtightness test at all; welded and cryogenic containers alike are exempt from coating checks and airtightness tests until the next periodic inspection"],
 "Article 157-1."),

(L,"第158條",2,"高壓氣體容器-定期效期",
 "高壓氣體容器經定期檢查合格者，其使用有效期限最長為何？固定於車輛之罐槽體如何處理？",
 ["應依第一百五十五條規定之期限於原檢查合格證上簽署並註明使用有效期限，最長為五年；但固定於車輛之罐槽體者，應重新換發新證","應依第一百五十五條規定之期限於原檢查合格證上簽署並註明使用有效期限，最長為二年；但固定於車輛之罐槽體者，仍於原證簽署即可","應一律重新核發檢查合格證並註明使用有效期限，最長為十年；至於固定於車輛之罐槽體者，得由雇主自行於原證上註記其有效期限","應一律重新核發檢查合格證並註明使用有效期限，最長為一年；至於固定於車輛之罐槽體者，應報請中央主管機關核定其有效期限"],"a",
 "第158條：檢查機構對經定期檢查合格之高壓氣體容器，應依第155條規定之期限，於原檢查合格證上簽署，註明使用有效期限，最長為五年；但固定於車輛之罐槽體者，應重新換發新證。檢查員並應填報高壓氣體容器定期檢查結果報告表，將結果通知雇主。第155條第2款第1目：固定於車輛之高壓氣體容器外部檢查每年一次。",
 "How long at most is a high pressure gas container valid after periodic inspection, and what of vehicle tanks?",
 ["The original certificate is endorsed under the Article 155 intervals for at most five years; for a tank body fixed to a vehicle a new certificate must be issued instead","The original certificate is endorsed under the Article 155 intervals for at most two years; for a tank body fixed to a vehicle endorsement of the original still suffices","A new certificate is always issued with a valid period of at most ten years; for a tank body fixed to a vehicle the employer may note the period on the original","A new certificate is always issued with a valid period of at most one year; for a tank body fixed to a vehicle the central competent authority fixes the period"],
 "Article 158; see Article 155."),

(L,"第159條",2,"高壓氣體容器-不合格",
 "高壓氣體容器經定期檢查不合格者，應如何處理？",
 ["檢查員應即於檢查合格證記事欄記載不合格情形並通知改善；情形嚴重有發生危害之虞者，應報請所屬檢查機構限制其最高使用壓力或禁止使用","檢查員應即註銷其檢查合格證並命令解體報廢該容器；情形輕微者始得於檢查合格證記事欄記載不合格情形，並限期一個月內完成各項改善","檢查員應即函報中央主管機關逕行裁處罰鍰；情形嚴重有發生危害之虞者，另由中央主管機關公告該事業單位名稱及不合格之具體情形","檢查員僅需以口頭告知雇主不合格之情形即可；是否限制最高使用壓力或禁止使用，由雇主依營運需要自行決定並作成書面紀錄留存備查"],"a",
 "第159條：高壓氣體容器經定期檢查不合格者，檢查員應即於檢查合格證記事欄內記載不合格情形並通知改善；其情形嚴重有發生危害之虞者，並應報請所屬檢查機構限制其最高使用壓力或禁止使用。鍋爐（第88條）、第一種壓力容器（第113條）、高壓氣體特定設備（第137條）亦同。",
 "What must be done when a high pressure gas container fails its periodic inspection?",
 ["The inspector notes the failure in the remarks column of the certificate and calls for improvement; if serious enough to risk harm, the agency limits the working pressure or bans use","The inspector cancels the certificate at once and orders the container scrapped; only in slight cases is the failure noted in the remarks column with one month allowed to improve","The inspector reports it to the central competent authority to impose a fine; if serious enough to risk harm, that authority announces the undertaking's name and the defects found","The inspector need only tell the employer orally; whether to limit the working pressure or stop use is left to the employer as its operations require, with a written record kept"],
 "Article 159."),

(L,"第160條",3,"高壓氣體容器-重新檢查",
 "高壓氣體容器有下列何種情事之一時，應由所有人或雇主申請重新檢查？",
 ["從外國進口、構造檢查重新檢查或定期檢查合格後經閒置一年以上擬恢復使用、經禁止使用擬恢復使用、擬提升最高灌裝壓力、擬變更灌裝氣體種類","從外國進口、構造檢查重新檢查或定期檢查合格後經閒置三個月以上擬恢復使用、更換操作人員、擬降低最高灌裝壓力、擬變更容器之塗裝顏色","變更容器閥之廠牌型號、更換壓力表、變更保養廠商、變更公司負責人、變更容器編號、變更容器所屬部門等管理性質事項之一者均應申請","僅限於從外國進口一種情事；其餘閒置一年以上、經禁止使用、提升最高灌裝壓力或變更灌裝氣體種類者，均得於下次定期檢查時一併辦理"],"a",
 "第160條：高壓氣體容器有從外國進口、構造檢查重新檢查定期檢查合格後經閒置一年以上擬恢復使用（但由檢查機構認可者不在此限）、經禁止使用擬恢復使用、擬提升最高灌裝壓力、擬變更灌裝氣體種類等情事之一者，應由所有人或雇主向檢查機構申請重新檢查；對外國進口具有相當檢查證明文件者，檢查機構得免除全部或一部之檢查。",
 "Which circumstances require the owner or employer to apply for a high pressure gas container's re-inspection?",
 ["Import from abroad; idleness over a year after a structural, re- or periodic inspection with use to resume; resumption after a ban; raising the maximum filling pressure; changing the kind of gas filled","Import from abroad; idleness over three months after a structural, re- or periodic inspection with use to resume; a change of operator; lowering the maximum filling pressure; changing the paint colour","Changing the brand and model of the container valve, replacing the pressure gauge, changing the maintenance contractor, the company head, the container number, or the department that owns it","Only import from abroad; idleness over a year, resumption after a ban, raising the maximum filling pressure or changing the kind of gas filled may all be handled at the next periodic inspection"],
 "Article 160."),

(L,"第161條",2,"高壓氣體容器-重新申請",
 "所有人或雇主申請高壓氣體容器重新檢查時，應檢附哪些書件？",
 ["高壓氣體容器明細表二份、構造詳圖及強度計算書各二份（檢查機構認無必要者得免檢附）、前經檢查合格證明文件或其影本","高壓氣體容器明細表一份、灌裝氣體種類申報表二份、容器搬運車輛清冊、駕駛人員名冊及灌氣容器儲存場所配置圖各一份","熔接明細表二份、熔接施工人員之熔接技術士資格證件、熔接程序規範及熔接程序資格檢定紀錄影本各一份等熔接相關文件","公司登記證明文件、工廠登記證影本、勞工保險投保名冊、自動檢查計畫及緊急應變計畫各一份等行政管理性質之相關文件"],"a",
 "第161條：所有人或雇主申請高壓氣體容器之重新檢查時，應填具高壓氣體容器重新檢查申請書，並檢附高壓氣體容器明細表二份、構造詳圖及強度計算書各二份（但檢查機構認無必要者得免檢附）、前經檢查合格證明文件或其影本；第151條第3項及第152條規定於重新檢查時準用之。",
 "What documents must accompany a re-inspection application for a high pressure gas container?",
 ["Two container specification tables, two sets each of detailed drawings and strength calculations (waivable if the agency finds them unnecessary), and the previous certificate or a copy","One container specification table, two declarations of the gases filled, a list of transport vehicles, the drivers' roster and a layout of the filled container storage site","Two welding schedules, the welders' skill certificates, and one copy each of the welding procedure specification and the welding procedure qualification records","The company registration documents, a copy of the factory registration, the labor insurance roster, the automatic inspection plan and the emergency response plan, one each"],
 "Article 161."),

(L,"第162條",2,"高壓氣體容器-重新合格",
 "高壓氣體容器經重新檢查合格者，檢查機構應如何處理？其有效期限為何？",
 ["應核發檢查合格證並註明使用有效期限；但符合閒置後恢復使用或經禁止使用擬恢復使用者，得在原合格證記載檢查日期結果及有效期限；有效期限準用第155條最長五年","應核發檢查合格證並註明使用有效期限；凡經重新檢查合格者一律不得於原合格證記載，均須重新換發新證；有效期限一律自核發之日起算，最長為二年而不得延長","應僅於容器明細表加蓋重新檢查合格戳記，檢查合格證須俟竣工檢查合格後始得核發；有效期限準用第一百五十八條之規定，最長為一年並得由雇主自行延長之","應僅將檢查結果以書面通知申請人並由其留存備查，不核發任何檢查合格證；有效期限由所有人依容器實際使用狀況自行認定，最長以十年為限並報請備查"],"a",
 "第162條：高壓氣體容器經重新檢查合格者，檢查機構應核發檢查合格證，並註明使用有效期限；但符合第160條第2款（閒置一年以上擬恢復使用）或第3款（經禁止使用擬恢復使用），經檢查合格者，得在原檢查合格證上記載檢查日期、檢查結果及註明使用有效期限。前項檢查合格證有效期限準用第155條，最長為五年；外國進口者應在被檢查物體上明顯部位打印。",
 "How does the agency handle a high pressure gas container passing re-inspection, and for how long?",
 ["It issues an inspection certificate noting the valid period; where use resumes after idleness or a ban, the original certificate may instead be endorsed with the date, result and period; the period follows Article 155, at most five years","It issues an inspection certificate noting the valid period; no container passing re-inspection may have the original certificate endorsed, a new one always being issued running from issue for at most two years without extension","It only stamps the container specification table with the re-inspection pass mark, the certificate issuing after the completion inspection; the period follows Article 158, at most one year and extendable by the employer","It only notifies the applicant of the result in writing for the applicant's own records, issuing no certificate; the owner itself fixes the valid period from actual condition, at most ten years, and files it for recordation"],
 "Article 162; see Articles 155 and 160."),

(L,"第162之1條",2,"高壓氣體容器-變更檢查",
 "高壓氣體容器經修改致何種情形時應申請變更檢查？合格後如何處理？",
 ["經修改致其構造部分有變動者，所有人或雇主應向檢查機構申請變更檢查；合格者由檢查員在原檢查合格證記事欄記載檢查日期、變更部分及檢查結果","經修改致其灌裝氣體種類有變動者，所有人或雇主應向檢查機構申請變更檢查；合格者應由檢查機構重新核發新檢查合格證並重新起算其使用有效期限","經修改致其塗裝顏色或標示內容有變動者，雇主應向當地主管機關申請變更檢查；合格者由主管機關函知檢查機構於原合格證上加註變更之部分及結果","經修改致其容器閥或壓力表廠牌有變動者，製造人應向中央主管機關申請變更檢查；合格者由中央主管機關公告其變更內容並通知原發證之檢查機構"],"a",
 "第162條之1：高壓氣體容器經修改致其構造部分有變動者，所有人或雇主應向檢查機構申請變更檢查；高壓氣體容器經變更檢查合格者，檢查員應在原檢查合格證記事欄內記載檢查日期、變更部分及檢查結果。至於擬變更灌裝氣體種類者，則屬第160條應申請重新檢查之情形。",
 "When must a high pressure gas container undergo an alteration inspection, and what follows on passing?",
 ["Where modification changes its structural parts, the owner or employer applies for an alteration inspection; on passing, the inspector notes the date, the altered part and the result in the remarks column","Where modification changes the kind of gas filled, the owner or employer applies for an alteration inspection; on passing, the agency issues a brand new certificate and the valid period starts afresh","Where modification changes the paint colour or the markings, the employer applies to the local competent authority; on passing, that authority tells the agency to note the change on the certificate","Where the brand of the container valve or pressure gauge changes, the maker applies to the central competent authority; on passing, that authority announces the change and informs the issuing agency"],
 "Article 162-1; cf. Article 160."),

(L,"第162之2條",2,"高壓氣體容器-變更申請",
 "所有人或雇主申請高壓氣體容器變更檢查時，應檢附哪些書件？",
 ["製造設施型式檢查合格證明、容器明細表二份、變更部分圖件、構造詳圖及強度計算書各二份（檢查機構認無必要者得免）、前經檢查合格證明或其影本","製造設施型式檢查合格證明、熔接明細表二份、熔接技術士資格證件、熔接程序規範及熔接程序資格檢定紀錄影本各一份等熔接品質相關之證明文件","灌裝氣體種類申報表二份、容器搬運車輛清冊、駕駛人員名冊、灌氣容器儲存場所配置圖及最近一次定期檢查結果報告表影本各一份等文件","公司登記證明文件、工廠登記證影本、最近三年財務報表、勞工保險投保名冊及職業安全衛生管理計畫各一份等行政管理性質之相關文件"],"a",
 "第162條之2：所有人或雇主申請高壓氣體容器變更檢查時，應填具高壓氣體容器變更檢查申請書一份，並檢附製造設施型式檢查合格證明、高壓氣體容器明細表二份、變更部分圖件、構造詳圖及強度計算書各二份（但檢查機構認無必要者得免檢附）、前經檢查合格證明或其影本；第151條第3項及第152條規定於變更檢查時準用之。",
 "What documents must accompany an alteration inspection application for a high pressure gas container?",
 ["The facility type inspection certificate, two container specification tables, drawings of the altered part, two sets each of detailed drawings and strength calculations (waivable), and the previous certificate or a copy","The facility type inspection certificate, two welding schedules, the welders' skill certificates and one copy each of the welding procedure specification and the welding procedure qualification records","Two declarations of the gases filled, a list of transport vehicles, the drivers' roster, a layout of the filled container storage site and one copy of the latest periodic inspection result report","The company registration documents, a copy of the factory registration, three years of financial statements, the labor insurance roster and the occupational safety and health management plan"],
 "Article 162-2."),

(L,"第164條",1,"危機規則-停用報備",
 "雇主停用危險性機械或設備，其停用期間超過檢查合格證有效期限者，應如何辦理？",
 ["應向檢查機構報備","應向中央主管機關申請核准後備查","應逕行繳銷其檢查合格證","應由製造人代為申請廢用登記"],"a",
 "第164條：雇主停用危險性機械或設備時，停用期間超過檢查合格證有效期限者，應向檢查機構報備。第163條：對於不堪使用或擬不再使用者，應填具廢用申請書向檢查機構繳銷檢查合格證，經辦妥廢用申請者不得以任何理由申請恢復使用。停用超過有效期限一年以上擬恢復使用者，另須申請重新檢查。",
 "What must an employer do when a dangerous machine is idled beyond its certificate's valid period?",
 ["File a report with the inspection agency","Apply to the central competent authority for approval","Surrender and cancel the inspection certificate at once","Have the manufacturer file a disuse registration for it"],
 "Article 164; cf. Article 163."),

(L,"第165條",1,"危機規則-轉讓換證",
 "危險性機械或設備轉讓時，應由何人向何機構辦理何事？",
 ["應由受讓人向當地檢查機構申請換發檢查合格證","應由讓與人向原發證檢查機構申請註銷檢查合格證","應由製造人向中央主管機關申請重新辦理型式檢查","應由受讓人向當地主管機關報備後逕行使用原合格證"],"a",
 "第165條：危險性機械或設備轉讓時，應由受讓人向當地檢查機構申請換發檢查合格證。第166條：檢查合格證遺失或損毀時，應填具檢查合格證補發申請書，向原發證檢查機構申請補發或換發。",
 "When a dangerous machine or equipment is transferred, who must do what and where?",
 ["The transferee applies to the local inspection agency for a reissued certificate","The transferor applies to the issuing agency to cancel the inspection certificate","The manufacturer applies to the central competent authority for a fresh type inspection","The transferee files with the local competent authority and keeps using the old certificate"],
 "Article 165."),

(L,"第166條",1,"危機規則-補發合格證",
 "危險性機械或設備之檢查合格證遺失或損毀時，應如何辦理？",
 ["應填具檢查合格證補發申請書，向原發證檢查機構申請補發或換發","應填具檢查合格證補發申請書，向中央主管機關申請補發或換發","應重新申請竣工檢查或使用檢查，經合格後始得核發新檢查合格證","應由雇主自行影印留存並報請當地主管機關備查，無須申請補發"],"a",
 "第166條：危險性機械或設備檢查合格證遺失或損毀時，應填具檢查合格證補發申請書（附表四十七），向原發證檢查機構申請補發或換發。第165條：轉讓時則由受讓人向當地檢查機構申請換發檢查合格證。",
 "What is to be done when a dangerous machine's inspection certificate is lost or damaged?",
 ["File a reissue application with the inspection agency that originally issued the certificate","File a reissue application with the central competent authority for it to reissue or replace","Apply afresh for a completion or use inspection, a new certificate issuing only on passing","The employer keeps a photocopy and files it locally, no reissue application being needed"],
 "Article 166."),

(L,"第167條",2,"危機規則-效期起算",
 "定期檢查合格之危險性機械或設備，其檢查合格證有效期限如何起算？",
 ["自檢查合格日起算；但該項檢查於檢查合格證有效期限屆滿前三個月內辦理完竣者，自檢查合格證有效期限屆滿日之次日起算","自檢查合格日起算；縱該項檢查於檢查合格證有效期限屆滿前三個月內辦竣，仍一律自實際檢查合格之當日起算而不得順延","自申請定期檢查之日起算；但該項檢查於檢查合格證有效期限屆滿後始辦竣者，改自檢查合格證有效期限屆滿日起算之","自檢查合格證核發之日起算；但該項檢查於檢查合格證有效期限屆滿前六個月內辦竣者，自次年一月一日起重新起算之"],"a",
 "第167條：定期檢查合格之危險性機械或設備，其檢查合格證有效期限，自檢查合格日起算；但該項檢查於檢查合格證有效期限屆滿前三個月內辦理完竣者，自檢查合格證有效期限屆滿日之次日起算。此一規定可避免提前受檢者反而縮短其使用期限。",
 "How is the valid period of a certificate reckoned after a periodic inspection is passed?",
 ["From the date the inspection is passed; but where it is completed within three months before the certificate expires, from the day after that expiry date","From the date the inspection is passed; even where it is completed within three months before expiry, it always runs from the actual pass date with no deferral","From the date the periodic inspection is applied for; but where it is completed after the certificate has expired, from the date of that expiry instead","From the date the certificate is issued; but where it is completed within six months before expiry, it restarts from the first day of the following year"],
 "Article 167."),

(L,"第167之1條",2,"危機規則-既有設備",
 "納入職業安全衛生法適用範圍前，或本規則發布施行前已設置之危險性機械及設備，其檢查如何辦理？",
 ["得依既有危險性機械及設備安全檢查規則辦理","應一律依本規則辦理型式檢查及構造檢查","應報請中央主管機關逐案核定其檢查方式","應由雇主自行檢查並作成紀錄留存備查即可"],"a",
 "第167條之1：納入本法適用範圍前，或本規則發布施行前已設置之危險性機械及設備之檢查，得依既有危險性機械及設備安全檢查規則辦理。該規則第3條並明定申請檢查時，得不受本規則所定型式檢查、熔接檢查及構造檢查等規定之限制。",
 "How are dangerous machines installed before the Act or these Rules applied to them inspected?",
 ["They may be inspected under the Rules for Safety Inspection of Existing Dangerous Machinery and Equipment","They must all undergo the type inspection and structural inspection prescribed by these Rules","The central competent authority must decide the manner of inspection case by case for each","The employer may simply inspect them itself and keep a record of the inspection on file"],
 "Article 167-1."),

(L,"第167之2條",1,"危機規則-自營作業者",
 "本規則有關雇主義務之規定，對自營作業者如何適用？",
 ["自營作業者準用本規則有關雇主義務之規定","自營作業者完全不適用本規則之任何規定","自營作業者僅適用有關製造人義務之規定","自營作業者由中央主管機關另定辦法規範"],"a",
 "第167條之2：自營作業者，準用本規則有關雇主義務之規定。既有危險性機械及設備安全檢查規則第19條之1亦有相同規定。職業安全衛生法第51條第1項亦定有自營作業者準用相關規定之明文。",
 "How do these Rules' employer obligations apply to a self-employed worker?",
 ["A self-employed worker is subject mutatis mutandis to the employer obligations","A self-employed worker is entirely outside the scope of these Rules altogether","A self-employed worker is subject only to the obligations placed on manufacturers","A self-employed worker is governed by separate regulations set by the authority"],
 "Article 167-2."),

(L,"第168條",2,"危機規則-施行日期",
 "本規則之施行日期，下列敘述何者正確？",
 ["自發布日施行；但第九條、第二十二條、第三十二條、第四十二條、第五十二條、第六十二條規定，自本規則發布後一年施行","自發布日施行；且全部條文均自發布日同時施行，並無任何條文延後施行或另定施行日期之特別規定存在其中","自發布後六個月施行；但有關型式檢查之各該條文，得由中央主管機關公告延後至發布後三年施行以利業者因應","自公布日後第三日起發生效力；至於型式檢查、熔接檢查及構造檢查等條文，均自中央主管機關另行公告日施行"],"a",
 "第168條：本規則自發布日施行；但第9條、第22條、第32條、第42條、第52條、第62條（各類危險性機械之型式檢查）規定，自本規則發布後一年施行。修正條文除一百零三年六月二十七日修正發布之條文自一百零三年七月三日施行、一百十四年十二月二十三日修正發布之第3條、第19條、第29條自發布後一年施行外，自發布日施行。",
 "Which statement about the commencement of these Rules is correct?",
 ["They take effect on promulgation, save that Articles 9, 22, 32, 42, 52 and 62 take effect one year after the Rules are promulgated","They take effect on promulgation, and every article takes effect at the same time, no article being deferred or separately commenced","They take effect six months after promulgation, though the type inspection articles may be deferred by announcement to three years","They take effect on the third day after publication, while the type, welding and structural inspection articles await an announcement"],
 "Article 168."),

# ---------- 既有危險性機械及設備安全檢查規則（OSH-54） ----------
(E,"第1條",1,"既有危機-法源",
 "既有危險性機械及設備安全檢查規則之訂定目的及法源依據為何？",
 ["為使既有危險性機械及設備納入檢查管理，依職業安全衛生法第十六條第四項規定訂定","為使既有危險性機械及設備納入檢查管理，依勞動檢查法第二十六條第二項規定訂定","為提升危險性機械製造品質，依職業安全衛生法第六條第三項之授權規定訂定本規則","為規範代行檢查機構之管理，依職業安全衛生法第十六條第三項之授權規定訂定本規則"],"a",
 "第1條：為使既有危險性機械及設備納入檢查管理，依職業安全衛生法（以下簡稱本法）第十六條第四項規定訂定本規則。第2條第2項：本規則未規定者，適用危險性機械及設備安全檢查規則之規定。",
 "What is the purpose and legal basis of the Rules for Existing Dangerous Machinery and Equipment?",
 ["To bring existing dangerous machinery and equipment under inspection control, adopted under Article 16(4) of the Occupational Safety and Health Act","To bring existing dangerous machinery and equipment under inspection control, adopted under Article 26(2) of the Labor Inspection Act of Taiwan","To raise the manufacturing quality of dangerous machinery, adopted under the authorisation in Article 6(3) of the Occupational Safety and Health Act","To regulate the management of designated inspection bodies, adopted under the authorisation in Article 16(3) of the Occupational Safety and Health Act"],
 "Article 1."),

(E,"第3條",2,"既有危機-檢查限制",
 "事業單位對既有危險性機械及設備申請檢查時，得不受哪些規定之限制？",
 ["得不受危險性機械及設備安全檢查規則所定型式檢查、熔接檢查及構造檢查等規定之限制","得不受危險性機械及設備安全檢查規則所定竣工檢查、使用檢查及定期檢查等規定之限制","得不受職業安全衛生法有關雇主應使勞工接受安全衛生教育訓練等相關規定之限制","得不受勞動檢查法有關勞動檢查機構得實施檢查及要求提供資料等相關規定之限制"],"a",
 "第3條：事業單位對於既有危險性機械及設備，依本法第十六條規定，向勞動檢查機構或中央主管機關指定之代行檢查機構（合稱檢查機構）申請檢查時，得不受危險性機械及設備安全檢查規則所定型式檢查、熔接檢查及構造檢查等規定之限制。第9條：既有危險性機械檢查項目仍依該規則所定竣工檢查或使用檢查項目。",
 "From which requirements is an application for inspection of existing dangerous machinery exempt?",
 ["From the type inspection, welding inspection and structural inspection requirements of the general Safety Inspection Rules","From the completion inspection, use inspection and periodic inspection requirements of the general Safety Inspection Rules","From the Occupational Safety and Health Act's requirements that the employer provide safety and health training to workers","From the Labor Inspection Act's provisions allowing inspection agencies to inspect and to demand the production of data"],
 "Article 3; cf. Article 9."),

(E,"第4條",2,"既有危機-機械申請",
 "事業單位申請既有危險性機械檢查時，應檢附哪些書件？",
 ["組配圖及強度計算書、固定式起重機之設置場所平面圖及基礎概要、營建用升降機之設置場所四周狀況圖、人字臂起重桿或吊籠之設置固定方式、符合設置時間之相關證明文件","構造詳圖及強度計算書、熔接部之機械試驗結果、必要之非破壞試驗結果、安全閥構造圖及必要吹洩量計算書、設備設置場所及周圍狀況圖、符合設置時間之相關證明文件","製造設施型式檢查合格證明、熔接檢查合格之熔接明細表、構造檢查合格之明細表、荷重試驗及安定性試驗紀錄、操作人員名冊及訓練證書、最近一年之保養維修紀錄","公司登記證明文件及工廠登記證影本、勞工保險投保名冊、職業安全衛生管理計畫、自動檢查計畫、緊急應變計畫及承攬商管理辦法等行政管理性質之相關文件資料"],"a",
 "第4條：事業單位申請既有危險性機械檢查時，應填具檢查申請書（附表一）及明細表，並檢附組配圖及強度計算書、固定式起重機之設置場所平面圖及基礎概要、營建用升降機之設置場所四周狀況圖、人字臂起重桿或吊籠之設置固定方式、符合第2條規定之設置時間相關證明文件；明細表依危險性機械及設備安全檢查規則所定格式。",
 "What documents must accompany an application to inspect existing dangerous machinery?",
 ["Assembly drawing and strength calculations, site plan and foundation outline for a fixed crane, surroundings drawing for a construction lift, the fixing method for a derrick or cradle, and proof of the installation date","Detailed structural drawings and strength calculations, mechanical test results for welds, necessary non-destructive test results, safety valve drawings and blow-off calculations, site and surroundings drawings, and proof of the date","The facility type inspection certificate, a stamped welding schedule, a stamped structural specification table, load and stability test records, the operator roster and training certificates, and a year of maintenance records","The company registration and a copy of the factory registration, the labor insurance roster, the safety and health management plan, the automatic inspection plan, the emergency response plan and the contractor management rules"],
 "Article 4."),

(E,"第6條",2,"既有危機-荷重核定",
 "檢查機構對既有危險性機械之吊升荷重或積載荷重，應如何核定？",
 ["書件資料齊全者得依原設計內容審查並依檢查結果核定；資料不齊全者，得依其提供之構造明細表、組配圖、強度計算書等文件審查並依檢查結果核定","書件資料齊全者得依原設計內容審查並依檢查結果核定；資料不齊全者，一律不予受理檢查，應俟事業單位補齊全部原始資料後始得重新提出申請","不論書件是否齊全，均應依現行國家標準重新設計計算後核定；事業單位無法提出原始設計資料者，其吊升荷重或積載荷重一律核定為零而不得使用","不論書件是否齊全，均由事業單位自行核定吊升荷重或積載荷重並報請檢查機構備查；檢查機構僅就其申報內容實施書面審查而不實施現場檢查"],"a",
 "第6條：檢查機構對於事業單位依第4條檢附之書件資料齊全者，於實施檢查時得依原設計內容審查，並依檢查結果核定既有危險性機械之吊升荷重或積載荷重；事業單位檢附證明資料不齊全者，檢查機構得依其提供之構造明細表、組配圖、強度計算書等相關文件審查，並依檢查結果核定吊升荷重或積載荷重。第5條另定原始資料欠缺時之採認方式。",
 "How is the lifting or carrying load of existing dangerous machinery determined?",
 ["If the documents are complete, review may follow the original design and the load is fixed on the inspection result; if incomplete, the agency reviews the specification table, assembly drawing and strength calculations submitted","If the documents are complete, review may follow the original design and the load is fixed on the inspection result; if incomplete, the application is refused until every original document has been supplied afresh","Whether or not documents are complete, the load must be recalculated to current national standards; where no original design data can be produced the load is fixed at zero and the machine may not be used","Whether or not documents are complete, the undertaking fixes the lifting or carrying load itself and files it; the agency reviews only the declaration on paper and carries out no on-site inspection at all"],
 "Article 6; cf. Article 5."),

(E,"第7條",1,"既有危機-受理通知",
 "檢查機構對事業單位申請既有危險性機械及設備檢查，應於何時通知檢查日期？",
 ["應於受理檢查後，將檢查日期通知申請人","應於受理檢查前，將檢查日期公告於網站","應於檢查完成後，將檢查日期通知申請人","應於受理檢查後三十日內，通知中央主管機關"],"a",
 "第7條：檢查機構對事業單位申請既有危險性機械及設備檢查，應於受理檢查後，將檢查日期通知申請人。第8條、第14條並分別規定雇主或其指派人員應在場及事前應完成之準備事項。",
 "When must the agency notify the inspection date for existing dangerous machinery or equipment?",
 ["After accepting the application, it notifies the applicant of the inspection date","Before accepting the application, it publishes the inspection date on its website","After the inspection is finished, it notifies the applicant of the inspection date","Within thirty days of accepting it, it notifies the central competent authority"],
 "Article 7."),

(E,"第8條",1,"既有危機-機械準備",
 "檢查機構實施既有危險性機械檢查時，雇主應如何配合？",
 ["雇主或其指派人員應在場，並應事先準備荷重試驗、安定性試驗用荷物及必要之吊掛器具","雇主或其指派人員應在場，並應事先將受檢查物件放置於易檢查位置及準備水壓耐壓試驗","雇主得不必到場，僅須事先準備荷重試驗用荷物並委由製造人代為說明該機械之構造性能","雇主或其指派人員應在場，並應事先完成非破壞檢查及超音波測厚並提出檢測報告供審查"],"a",
 "第8條：檢查機構實施既有危險性機械檢查時，雇主或其指派人員應在場，並應事先準備荷重試驗、安定性試驗用荷物及必要之吊掛器具。第14條：實施既有危險性設備檢查時，則應事先將受檢查物件放置於易檢查位置並準備水壓等耐壓試驗。",
 "How must the employer cooperate when existing dangerous machinery is inspected?",
 ["The employer or a designee must attend and must prepare in advance the loads for the load and stability tests and the necessary rigging gear","The employer or a designee must attend and must place the object where it is easy to inspect and prepare a hydrostatic pressure test beforehand","The employer need not attend and need only prepare the load test loads, leaving the maker to explain the structure and performance of the machine","The employer or a designee must attend and must complete non-destructive testing and ultrasonic thickness measurement and submit the reports for review"],
 "Article 8; cf. Article 14."),

(E,"第9條",1,"既有危機-檢查項目",
 "既有危險性機械之檢查項目，應依何規定辦理？",
 ["依危險性機械及設備安全檢查規則所定竣工檢查或使用檢查項目","依危險性機械及設備安全檢查規則所定型式檢查或熔接檢查項目","依中央主管機關就個案另行指定之檢查項目，逐案核定後辦理","依事業單位自行擬訂並報經檢查機構同意之檢查項目清單辦理"],"a",
 "第9條：既有危險性機械檢查項目，依危險性機械及設備安全檢查規則所定竣工檢查或使用檢查項目。第3條雖免除型式檢查、熔接檢查及構造檢查之限制，但竣工檢查或使用檢查之實質項目仍應依原規則辦理。第15條則另定既有危險性設備之檢查項目。",
 "Which inspection items apply to existing dangerous machinery?",
 ["The completion inspection or use inspection items laid down in the general Safety Inspection Rules","The type inspection or welding inspection items laid down in the general Safety Inspection Rules","Items designated separately by the central competent authority and approved case by case","A list of items drawn up by the undertaking itself and agreed to by the inspection agency"],
 "Article 9."),

(E,"第10條",3,"既有危機-空間不足",
 "既有危險性機械與建築物間設置空間不足而無礙使用安全者，得如何辦理？",
 ["保養檢修時將架空式起重機駛至兩橫樑間固定，使屋頂與人行道間保持一點八公尺以上或於人行道設高一點五公尺以上有簷頂蓬並懸掛警告標示；無法設人行道者得改設具防墜設施之檢點台","保養檢修時將架空式起重機駛至兩橫樑間固定，使屋頂與人行道間保持二點五公尺以上或於人行道設高二公尺以上有簷頂蓬並懸掛警告標示；無法設人行道者應一律拆除該起重機","應一律依現行規定補足設置空間，無法補足者不得申請檢查；至於營建用升降機之頂部安全距離或機坑深度不足者，亦應改建至符合規定後始得申請辦理各項之檢查","得由事業單位自行評估並作成紀錄留存備查即可；至於架空式起重機之人行道、頂蓬高度及營建用升降機之頂部安全距離，均由雇主視現場狀況自行決定其規格"],"a",
 "第10條：既有危險性機械與建築物間之設置空間不足，如無礙使用安全者，得依下列規定辦理並註記於相關檢查文件：一、於保養、檢修時，將架空式起重機駛至兩橫樑間加以固定，使屋頂與其人行道間保持一點八公尺以上，或於其人行道設置高一點五公尺以上有簷之頂蓬，並於顯著地點懸掛警告標示。二、架空式起重機無法依規定設置人行道時，得改設具有防止人員墜落設施之檢點台。三、營建用升降機之頂部安全距離或機坑深度不足者，得採取維修保養之必要安全設施及措施，並顯著標示。",
 "What may be done where space between existing machinery and the building is insufficient but use is still safe?",
 ["Park and secure an overhead crane between girders for maintenance so that 1.8 m clearance is kept above the walkway, or provide a hooded canopy at least 1.5 m high with warning signs; where no walkway is possible, an inspection platform with fall protection may replace it","Park and secure an overhead crane between girders for maintenance so that 2.5 m clearance is kept above the walkway, or provide a hooded canopy at least 2 m high with warning signs; where no walkway is possible, the crane must be dismantled altogether","The space must always be brought up to current requirements, and where it cannot be, no inspection may be applied for; a construction lift with insufficient top clearance or pit depth must likewise be rebuilt to standard before any inspection","The undertaking may simply assess it itself and keep a record; the walkway, canopy height for an overhead crane and the top clearance of a construction lift are all left to the employer to settle according to the conditions on site"],
 "Article 10."),

(E,"第11條",2,"既有危機-設備申請",
 "事業單位申請既有危險性設備檢查時，應檢附哪些書件？",
 ["構造詳圖及強度計算書、熔接部之機械試驗結果、必要之非破壞試驗結果、安全閥構造圖及必要吹洩量計算書、設備設置場所及其周圍狀況圖、符合設置時間之相關證明文件","組配圖及強度計算書、固定式起重機之設置場所平面圖及基礎概要、營建用升降機之四周狀況圖、人字臂起重桿或吊籠之設置固定方式、符合設置時間之相關證明文件","製造設施型式檢查合格證明、加蓋熔接檢查合格戳記之熔接明細表、加蓋構造檢查合格戳記之明細表、耐壓試驗紀錄、氣密試驗紀錄及最近一年之保養維修紀錄","公司登記證明文件及工廠登記證影本、勞工保險投保名冊、職業安全衛生管理計畫、自動檢查計畫、緊急應變計畫及教育訓練紀錄等行政管理性質之相關文件"],"a",
 "第11條：事業單位申請既有危險性設備檢查時，應填具檢查申請書（附表二）及明細表，並檢附構造詳圖及強度計算書、熔接部之機械試驗結果、必要之非破壞試驗結果、安全閥構造圖及必要吹洩量計算書、設備設置場所及其周圍狀況圖、符合第2條規定之設置時間相關證明文件；明細表依危險性機械及設備安全檢查規則所定格式。",
 "What documents must accompany an application to inspect existing dangerous equipment?",
 ["Detailed structural drawings and strength calculations, mechanical test results for the welds, necessary non-destructive test results, safety valve drawings and blow-off calculations, drawings of the site and surroundings, and proof of the installation date","Assembly drawing and strength calculations, the site plan and foundation outline for a fixed crane, a surroundings drawing for a construction lift, the fixing method for a derrick or cradle, and proof of the installation date of the machine","The facility type inspection certificate, a welding schedule bearing the welding pass stamp, a specification table bearing the structural pass stamp, pressure test records, airtightness test records and a year of maintenance records","The company registration and a copy of the factory registration, the labor insurance roster, the safety and health management plan, the automatic inspection plan, the emergency response plan and the training records kept"],
 "Article 11."),

(E,"第12條",3,"既有危機-設備採認",
 "既有危險性設備之原始資料欠缺者，檢查機構得依哪些方式辦理？",
 ["具原製造廠簽署證明文件者得以資料審查認定放射線檢查熔接效率材質及強度；材質不明者依最低強度採計；未附熔接部機械試驗結果或強度計算書不全者，事業單位如實施爐筒胴體端板管板等主要結構強度計算並經執業之機械技師簽認，得予採認","具原製造廠簽署證明文件者得以資料審查認定放射線檢查熔接效率材質及強度；材質不明者依最高強度採計；未附熔接部機械試驗結果者，一律應重新實施破壞性試驗及非破壞檢查，不得以強度計算書及技師簽認方式採認之","不論有無原製造廠證明文件，均應依現行國家標準重新實施材料試驗及非破壞檢查；材質不明者一律不予採認；強度計算書不全者，應委由原製造廠重新出具完整之強度計算書後始得申請辦理各項檢查","不論資料是否欠缺，均由事業單位自行認定材質及強度並作成紀錄留存備查；檢查機構僅就其提送之紀錄實施書面審查，如認有疑義時，得要求事業單位委請執業之機械技師出具意見書供參考"],"a",
 "第12條：事業單位依第11條檢附書件之原始資料欠缺者，檢查機構依下列規定辦理：具有原製造廠簽署之相關證明文件者，得以資料審查方式認定放射線檢查、熔接效率、材質及強度；使用材質不明者，得依最低強度採計；得依原設計標準或製造當時之相關標準實施強度計算；具有前經熔接、構造檢查合格打印號碼可資識別者，得予採認；自行繪製之整體組配構造詳圖並註明容器內徑長度端板管板型式厚度孔之尺寸位置傳熱管配置者，得予採認；未檢附熔接部機械試驗結果、非破壞試驗結果或強度計算書不全者，如實施爐筒胴體端板管板等主要結構之強度計算，經執業之機械技師簽認後，得予採認。",
 "Where original data on existing dangerous equipment is lacking, how may the agency proceed?",
 ["With papers signed by the original maker, radiography, weld efficiency, material and strength may be accepted on a documentary review; unknown material is taken at its lowest strength; missing weld test results or incomplete calculations may be accepted if the undertaking calculates the strength of the furnace, shell and plates and a practising mechanical engineer certifies it","With papers signed by the original maker, radiography, weld efficiency, material and strength may be accepted on a documentary review; unknown material is taken at its highest strength; missing weld test results always require fresh destructive and non-destructive testing and may never be accepted on calculations certified by an engineer","Whether or not the original maker's papers exist, material testing and non-destructive testing must be redone to current national standards; unknown material is never accepted; where the strength calculations are incomplete the original maker must reissue a complete set before any inspection may be applied for at all","Whether or not data is lacking, the undertaking itself determines the material and strength and keeps a record; the agency reviews only the records submitted and, if in doubt, may ask the undertaking to obtain an opinion from a practising mechanical engineer for reference"],
 "Article 12."),

(E,"第13條",2,"既有危機-壓力核定",
 "檢查機構對既有危險性設備之最高使用壓力或設計壓力，應如何核定？",
 ["書件資料齊全者得依原設計內容審查並依檢查結果核定；資料不齊全者，得依其提供之構造明細表、構造詳圖、強度計算書、安全閥設定壓力等文件審查並依檢查結果核定","書件資料齊全者得依原設計內容審查並依檢查結果核定；資料不齊全者，一律不予受理檢查申請，應俟事業單位補齊全部原始設計資料後始得重新提出檢查之申請","不論書件是否齊全，均應依現行國家標準重新設計計算後核定；事業單位無法提出原始設計資料者，其最高使用壓力一律核定為常壓而不得於加壓狀態下使用","不論書件是否齊全，均由事業單位自行核定最高使用壓力或設計壓力並報請備查；檢查機構僅就其申報之內容實施書面審查，不再實施現場檢查及耐壓試驗"],"a",
 "第13條：檢查機構對於事業單位依第11條檢附之書件資料齊全者，於實施檢查時得依原設計內容審查，並依檢查結果核定其最高使用壓力或設計壓力；事業單位檢附證明資料不齊全者，檢查機構得依其提供之構造明細表、構造詳圖、強度計算書、安全閥設定壓力等相關文件審查，並依檢查結果核定最高使用壓力或設計壓力。",
 "How is the maximum working or design pressure of existing dangerous equipment determined?",
 ["If the documents are complete, review may follow the original design and the pressure is fixed on the inspection result; if incomplete, the agency reviews the specification table, detailed drawings, strength calculations and safety valve setting","If the documents are complete, review may follow the original design and the pressure is fixed on the inspection result; if incomplete, the application is refused until all the original design data has been supplied afresh","Whether or not documents are complete, the pressure must be recalculated to current national standards; where no original design data can be produced it is fixed at atmospheric and the equipment may not be pressurised","Whether or not documents are complete, the undertaking fixes the maximum working or design pressure itself and files it; the agency reviews only the declaration on paper and carries out no site inspection or pressure test"],
 "Article 13."),

(E,"第14條",1,"既有危機-設備準備",
 "檢查機構實施既有危險性設備檢查時，雇主應事先完成哪些準備事項？",
 ["雇主或其指派人員應在場，並應事先將受檢查物件放置於易檢查位置及準備水壓等耐壓試驗","雇主或其指派人員應在場，並應事先準備荷重試驗、安定性試驗用荷物及必要之吊掛器具","雇主得不必到場，僅須事先將受檢查物件放置於易檢查位置並委由製造人代為說明其構造","雇主或其指派人員應在場，並應事先完成放射線檢查及熱處理檢查並提出報告供審查認定"],"a",
 "第14條：檢查機構實施既有危險性設備檢查時，雇主或其指派人員應在場，並事先完成下列準備事項：一、應將受檢查物件放置於易檢查位置。二、準備水壓等耐壓試驗。第8條：既有危險性機械則應事先準備荷重試驗、安定性試驗用荷物及必要之吊掛器具。",
 "What must the employer prepare in advance for an inspection of existing dangerous equipment?",
 ["The employer or a designee must attend and must beforehand place the object where it is easy to inspect and prepare a hydrostatic or other pressure test","The employer or a designee must attend and must beforehand prepare the loads for the load and stability tests and the necessary rigging gear for lifting","The employer need not attend and need only place the object where it is easy to inspect, leaving the maker to explain the structure of the equipment","The employer or a designee must attend and must beforehand complete radiographic and heat treatment inspection and submit the reports for review"],
 "Article 14; cf. Article 8."),

(E,"第15條",2,"既有危機-設備項目",
 "既有危險性設備之檢查項目包括下列何者？",
 ["材料厚度、構造、尺寸、最高使用壓力、強度計算之審查、人孔、檢查孔、清掃孔、安全閥數量、吹洩試驗、壓力表數量、安全裝置、耐壓試驗及其他必要檢查項目","吊升荷重、積載荷重、荷重試驗、安定性試驗、安全裝置之設置及性能、電氣及機械部分之檢查、額定荷重標示、各種裝置之運行速率及其他必要之檢查項目","型式檢查、熔接檢查及構造檢查之全部項目，並應由製造人補辦製造設施型式檢查合格證明後，始得由事業單位申請辦理既有危險性設備之各項檢查","僅實施外觀檢查及書面審查，不實施耐壓試驗、吹洩試驗或安全閥數量之查核；至於材料厚度與強度計算，均由事業單位自行確認後報請備查即可"],"a",
 "第15條：既有危險性設備檢查項目為材料厚度、構造、尺寸、最高使用壓力、強度計算之審查、人孔、檢查孔、清掃孔、安全閥數量、吹洩試驗、壓力表數量、安全裝置、耐壓試驗及其他必要檢查項目。第17條並定有外部檢查及內部檢查之具體項目。",
 "What does the inspection of existing dangerous equipment cover?",
 ["Material thickness, structure, dimensions, maximum working pressure, review of strength calculations, manholes, inspection and cleaning holes, number of safety valves, blow-off testing, number of pressure gauges, safety devices, pressure testing and other necessary items","Lifting load, carrying load, load testing, stability testing, the provision and performance of safety devices, checks of electrical and mechanical parts, the marking of the rated load, the running speeds of the various devices and other necessary items","Every item of the type, welding and structural inspections, the maker first having to obtain the facility type inspection certificate before the undertaking may apply for any inspection of the existing dangerous equipment at all","Only visual inspection and a documentary review, with no pressure test, blow-off test or check of the number of safety valves; material thickness and strength calculations are simply confirmed by the undertaking and filed"],
 "Article 15; cf. Article 17."),

(E,"第17條",3,"既有危機-內外部檢查",
 "既有危險性設備之外部檢查及內部檢查，其項目及困難時之處理為何？",
 ["外部檢查為外觀檢查、外部腐蝕裂痕變形污穢洩漏之檢測、必要時之非破壞檢查、易腐蝕處定點超音波測厚等，發現洩漏得要求拆除保溫材被覆；內部檢查確有困難者得僅實施耐壓試驗，但應於歲修時補行實施","外部檢查為外觀檢查、外部腐蝕裂痕變形污穢洩漏之檢測、必要時之非破壞檢查、易腐蝕處定點超音波測厚等，惟不得要求拆除保溫材被覆；內部檢查確有困難者得完全免除，且無須於歲修時補行實施之","外部檢查僅實施外觀檢查而不包括非破壞檢查或超音波測厚；內部檢查確有困難者，得由事業單位委請執業之機械技師出具安全無虞證明書替代，並免實施耐壓試驗及後續歲修時之補行檢查","外部檢查與內部檢查之項目，均由檢查機構就個案逐案指定；如內部檢查確有困難者，應報請中央主管機關核准後，始得以耐壓試驗替代，並於次年歲修時補行實施內部檢查"],"a",
 "第17條：既有危險性設備檢查時，應實施外部檢查及內部檢查。外部檢查為外觀檢查、外部腐蝕、裂痕、變形、污穢、洩漏之檢測、必要時實施之非破壞檢查、易腐蝕處之定點超音波測厚及其他必要檢查；檢查機構如發現有洩漏等情形時，得要求事業單位拆除保溫材被覆。內部檢查為內部之表面檢查、厚度、腐蝕、裂痕、變形、污穢等檢測、耐壓試驗、必要時實施之非破壞檢查及其他必要檢查；內部檢查確有困難者，得僅實施耐壓試驗，但應於歲修時補行實施。",
 "What do the external and internal inspections of existing dangerous equipment cover, and what if they are difficult?",
 ["External: appearance, external corrosion, cracking, deformation, fouling and leakage, NDT where needed and spot thickness measurement, insulation being stripped if leakage is found; where internal inspection is genuinely difficult only a pressure test need be done, made up at the annual overhaul","External: appearance, external corrosion, cracking, deformation, fouling and leakage, NDT where needed and spot thickness measurement, but insulation may never be required to be stripped; where internal inspection is difficult it is wholly waived and need not be made up later","External inspection is confined to appearance and excludes non-destructive testing or thickness measurement; where internal inspection is difficult a practising mechanical engineer's safety certificate may replace it, with no pressure test and nothing to be made up at the overhaul","The items of both external and internal inspection are designated case by case by the agency; where internal inspection is genuinely difficult, the central competent authority must approve before a pressure test may replace it, with the internal inspection made up next year"],
 "Article 17."),

(E,"第18條",2,"既有危機-合格證明",
 "檢查機構對檢查合格之既有危險性機械及設備，應如何處理？其有效期限為何？",
 ["應在被檢查物體上明顯部位打印檢查號碼以資識別，並填具檢查結果報告表及核發檢查合格證明，有效期限為一年；但檢查機構得依檢查結果予以縮短之","應在被檢查物體上明顯部位打印檢查號碼以資識別，並填具檢查結果報告表及核發檢查合格證明，有效期限為五年；且不得依檢查結果予以縮短其期限","僅需填具檢查結果報告表送交事業單位存查，無須打印檢查號碼亦無須核發檢查合格證明；其有效期限由事業單位視設備狀況自行認定並報請備查","應報請中央主管機關核發檢查合格證明並公告於指定資訊網站，有效期限為三年；如檢查結果良好者，得由檢查機構延長為五年並註記於報告表"],"a",
 "第18條：檢查機構對於檢查合格之既有危險性機械及設備，應在被檢查物體上明顯部位打印檢查號碼，以資識別，並填具檢查結果報告表及核發檢查合格證明（附表三、附表四），其有效期限為一年；但檢查機構得依檢查結果，予以縮短之。檢查結果報告表依危險性機械及設備安全檢查規則所定格式。",
 "How does the agency deal with existing machinery or equipment that passes, and for how long is it valid?",
 ["It marks the inspection number conspicuously on the object for identification, files a result report and issues a certificate of compliance valid for one year, which the agency may shorten on the inspection results","It marks the inspection number conspicuously on the object for identification, files a result report and issues a certificate of compliance valid for five years, which may never be shortened at all","It need only file a result report with the undertaking, marking no inspection number and issuing no certificate; the undertaking itself fixes the valid period from the condition of the equipment","It asks the central competent authority to issue the certificate and publish it on the designated website for three years, extendable by the agency to five years where results are good"],
 "Article 18."),

(E,"第19條",1,"既有危機-定期檢查",
 "事業單位至遲應於既有危險性機械及設備檢查合格證明有效期限屆滿前多久申請定期檢查？",
 ["至遲應於有效期限屆滿前一個月，依危險性機械及設備安全檢查規則規定向檢查機構申請定期檢查","至遲應於有效期限屆滿前三個月，依危險性機械及設備安全檢查規則規定向檢查機構申請定期檢查","至遲應於有效期限屆滿後一個月內，依危險性機械及設備安全檢查規則規定向檢查機構申請定期檢查","至遲應於有效期限屆滿前六個月，依既有危險性機械及設備安全檢查規則規定向中央主管機關申請"],"a",
 "第19條：事業單位至遲應於既有危險性機械及設備檢查合格證明有效期限屆滿前一個月，依危險性機械及設備安全檢查規則之規定，向檢查機構申請定期檢查。第18條：既有危險性機械及設備之檢查合格證明有效期限為一年，檢查機構並得依檢查結果縮短之。",
 "How long before its certificate expires must an existing machine or equipment be submitted for periodic inspection?",
 ["At the latest one month before expiry, applying to the inspection agency under the general Safety Inspection Rules for dangerous machinery","At the latest three months before expiry, applying to the inspection agency under the general Safety Inspection Rules for dangerous machinery","At the latest within one month after expiry, applying to the inspection agency under the general Safety Inspection Rules for dangerous machinery","At the latest six months before expiry, applying to the central competent authority under these Rules for existing dangerous machinery"],
 "Article 19."),

(E,"第19之1條",1,"既有危機-自營作業者",
 "既有危險性機械及設備安全檢查規則有關雇主義務之規定，對自營作業者如何適用？",
 ["自營作業者，準用本規則有關雇主之義務規定","自營作業者完全不適用本規則之任何相關規定","自營作業者僅準用有關製造人之義務相關規定","自營作業者之義務由中央主管機關另行公告之"],"a",
 "第19條之1：自營作業者，準用本規則有關雇主之義務規定。危險性機械及設備安全檢查規則第167條之2亦有相同規定。職業安全衛生法第51條並就自營作業者準用相關規定設有明文。",
 "How do the employer obligations under these Rules apply to a self-employed worker?",
 ["A self-employed worker is subject mutatis mutandis to the employer obligations in these Rules","A self-employed worker is entirely outside every provision of these Rules and bound by none","A self-employed worker is subject only to the obligations these Rules place on manufacturers","A self-employed worker's obligations are announced separately by the competent authority"],
 "Article 19-1."),

(E,"第20條",2,"既有危機-施行日期",
 "既有危險性機械及設備安全檢查規則之施行日期為何？",
 ["本規則自發布日施行；中華民國一百零三年七月三日修正條文，自一百零三年七月三日施行","本規則自發布後一年施行；中華民國一百零三年七月三日修正條文，自發布後六個月施行","本規則自發布後六個月施行；其後歷次修正條文，均自中央主管機關另行公告之日施行","本規則自公布日後第三日起發生效力；其後歷次修正條文，均自次年一月一日起施行之"],"a",
 "第20條：本規則自發布日施行；本規則中華民國一百零三年七月三日修正條文，自一百零三年七月三日施行。第2條：本規則所稱既有危險性機械及設備，指職安法施行前、危險性機械及設備安全檢查規則施行前、國家標準或相關法規規範構造規格前、或中央主管機關指定適用國外檢查標準前，已設置且目前未經檢查合格者。",
 "When did the Rules for Existing Dangerous Machinery and Equipment take effect?",
 ["They take effect on promulgation; the amendments of 3 July 2014 take effect on 3 July 2014","They take effect one year after promulgation; the amendments of 3 July 2014 after six months","They take effect six months after promulgation, later amendments awaiting an announcement","They take effect on the third day after publication, later amendments on 1 January next year"],
 "Article 20."),
]
